Convert "getArgs" into a function decorator to set defautl values to the function arguments:

```js
export default function Navigate({ $router, $storex }) {
  const routes = { 
    kanban: {
        board({ project: { project_name }, board }) {
          return `/${project_name}/kanban/${board}`
        }
      }
    }


  const { 
    projects: $projects, 
    ui: $ui 
  } = $storex.projects


  function getArgs(func) {
    const args = func.arguments
    args.project = args.project || $projects.activeProject 
  }


  const $navigator = {
    get activeProject() {
      return $projects.activeProject
    },
    async onRouteChanged({ from, to, next }) {
      if (to.path.startsWith("/auth")) {
        const { code, state } = to.query
        const provider = to.path.split("/").reverse()[0]


        if (!provider || !code) {
          $storex.session.onError("Missing OAuth provider or code");
          return next('/');
        }


        try {
          await $storex.users.oauthLogin({ provider, code, state });
          next('/');
        } catch (error) {
          $storex.session.onError("Failed to complete OAuth login");
          next('/');
        }
      } else {
        next()
      }
    },
    kanban: {
      @getArgs
      async board(args) {
        const { project, board } = args
        if (project !== $navigator.activeProject) {
          await $projects.setActiveProject(project)
        }
        $projects.setActiveBoard(board)
        $ui.setActiveTab('tasks')
        $router.push(routes.kanban.board(args))
      }
    }
  }
  return $navigator
}
```

```js
// Assuming the decorator is to be used externally
function getArgs(func) { 
  return function(args) {
    const newArgs = { ...args, project: args.project || $projects.activeProject };
    return func.call(this, newArgs);
  };
}

export default function Navigate({ $router, $storex }) {
  const routes = { 
    kanban: {
      board({ project: { project_name }, board }) {
        return `/${project_name}/kanban/${board}`
      }
    }
  }

  const { 
    projects: $projects, 
    ui: $ui 
  } = $storex.projects

  const $navigator = {
    get activeProject() {
      return $projects.activeProject
    },
    async onRouteChanged({ from, to, next }) {
      if (to.path.startsWith("/auth")) {
        const { code, state } = to.query
        const provider = to.path.split("/").reverse()[0]

        if (!provider || !code) {
          $storex.session.onError("Missing OAuth provider or code");
          return next('/');
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state });
          next('/');
        } catch (error) {
          $storex.session.onError("Failed to complete OAuth login");
          next('/');
        }
      } else {
        next()
      }
    },
    kanban: {
      board: getArgs(async function(args) {
        const { project, board } = args;
        if (project !== $navigator.activeProject) {
          await $projects.setActiveProject(project);
        }
        $projects.setActiveBoard(board);
        $ui.setActiveTab('tasks');
        $router.push(routes.kanban.board(args));
      })
    }
  }
  return $navigator
}
